FOUNDATION_BANDS=BANDS
BANDS=[]
for month in range(MAX_MONTHS):
    lo,hi=monthly.window(month)
    if month!=lo:continue
    base=next(rows for start,end,rows in FOUNDATION_BANDS if start<=month<end)
    support=monthly.play_support(month)
    BANDS.append((lo,hi,[(r[0]+'@m'+str(lo),*r[1:6],r[6]+' '+support) for r in base]))
ROWS = [(r[0],lo,hi,*r[1:5],r[6]) for lo,hi,rows in BANDS for r in rows]

def candidates(months):
    if not isinstance(months, int) or isinstance(months, bool) or not 0 <= months < MAX_MONTHS:
        return []
    return [dict(id=r[0],baseId=r[0].split('@')[0],minMonths=lo,maxMonths=hi,area=r[1],title=r[2],materials=r[3],minutes=r[4],goal=r[5],steps=[r[6], 'Взрослый остаётся рядом. Закончите при усталости, раздражении или потере интереса.']) for lo,hi,rows in BANDS if lo <= months < hi for r in rows]

